:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c63ff;
  --accent: #ff6584;
  --text: #ffffff;
  --card-back: #3f3f5a;
  --card-radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 600px;
  background: var(--surface);
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.stats {
  font-size: 1.1rem;
  font-weight: 600;
  background: var(--bg);
  padding: 8px 16px;
  border-radius: 999px;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  aspect-ratio: 1 / 1;
  width: 100%;
}

.card {
  position: relative;
  background: var(--card-back);
  border-radius: var(--card-radius);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
  border: 2px solid transparent;
  outline: none;
  aspect-ratio: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  user-select: none;
}

.card:hover {
  transform: scale(1.05);
  background: #4a4a6a;
}

.card:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 101, 132, 0.4);
}

.card:active {
  transform: scale(0.97);
}

.card.flipped {
  background: var(--primary);
  cursor: default;
}

.card.matched {
  background: var(--accent);
  cursor: default;
  opacity: 0.8;
}

.card.flipped:hover,
.card.matched:hover {
  transform: none;
  background: var(--primary);
}

.card.matched:hover {
  background: var(--accent);
}

.win-message {
  text-align: center;
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--accent);
  padding: 12px;
  background: var(--bg);
  border-radius: 12px;
}

.new-game-btn {
  padding: 14px 24px;
  font-size: 1.1rem;
  font-weight: 600;
  background: var(--primary);
  color: var(--text);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  align-self: center;
  min-width: 160px;
}

.new-game-btn:hover {
  background: #5a52e0;
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.96);
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
    gap: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .board {
    gap: 8px;
  }
  .card {
    font-size: 1.2rem;
  }
}

@media (max-width: 360px) {
  .game-container {
    padding: 12px;
  }
  .board {
    gap: 6px;
  }
}

const COLORS = [
  '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
  '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
];

const board = document.getElementById('board');
const movesEl = document.getElementById('moves');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game');

let cards = [];
let flipped = [];
let moves = 0;
let lock = false;
let matchedPairs = 0;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createBoard() {
  board.innerHTML = '';
  cards = [];
  flipped = [];
  moves = 0;
  matchedPairs = 0;
  lock = false;
  winMessage.hidden = true;
  movesEl.textContent = 'Moves: 0';

  const deck = shuffle([...COLORS, ...COLORS]);

  deck.forEach((color, i) => {
    const card = document.createElement('button');
    card.className = 'card';
    card.dataset.color = color;
    card.dataset.index = i;
    card.setAttribute('aria-label', `Card ${i + 1}, hidden`);
    card.setAttribute('role', 'gridcell');
    card.addEventListener('click', () => handleFlip(card));
    board.appendChild(card);
    cards.push(card);
  });
}

function handleFlip(card) {
  if (lock) return;
  if (card.classList.contains('flipped') || card.classList.contains('matched')) return;
  if (flipped.includes(card)) return;

  card.classList.add('flipped');
  card.style.background = card.dataset.color;
  card.setAttribute('aria-label', `Card ${Number(card.dataset.index) + 1}, revealed`);
  flipped.push(card);

  if (flipped.length === 2) {
    moves++;
    movesEl.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  const [a, b] = flipped;
  if (a.dataset.color === b.dataset.color) {
    a.classList.add('matched');
    b.classList.add('matched');
    a.setAttribute('aria-label', `Card ${Number(a.dataset.index) + 1}, matched`);
    b.setAttribute('aria-label', `Card ${Number(b.dataset.index) + 1}, matched`);
    flipped = [];
    matchedPairs++;
    if (matchedPairs === COLORS.length) {
      winMessage.hidden = false;
      winMessage.textContent = `You win! 🎉 ${moves} moves`;
    }
  } else {
    lock = true;
    setTimeout(() => {
      a.classList.remove('flipped');
      b.classList.remove('flipped');
      a.style.background = '';
      b.style.background = '';
      a.setAttribute('aria-label', `Card ${Number(a.dataset.index) + 1}, hidden`);
      b.setAttribute('aria-label', `Card ${Number(b.dataset.index) + 1}, hidden`);
      flipped = [];
      lock = false;
    }, 800);
  }
}

newGameBtn.addEventListener('click', createBoard);

createBoard();
